### 2. Tests Unitarios con PHPUnit (`tests/FactorialTest.php`)

```php
<?php

declare(strict_types=1);

namespace App\Tests;

use PHPUnit\Framework\TestCase;

class FactorialTest extends TestCase
{
    /** @test */
    public function factorial_de_0_retorna_1(): void
    {
        $this->assertEquals(1, factorial(0));
    }

    /** @test */
    public function factorial_de_1_retorna_1(): void
    {
        $this->assertEquals(1, factorial(1));
    }

    /** @test */
    public function factorial_de_5_retorna_120(): void
    {
        $this->assertEquals(120, factorial(5));
    }

    /** @test */
    public function factorial_de_10_retorna_3628800(): void
    {
        $this->assertEquals(3628800, factorial(10));
    }

    /** @test */
    public function factorial_de_numero_negativo_lanza_excepcion(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage('El factorial no está definido para números negativos.');

        factorial(-1);
    }

    /** @test */
    public function factorial_de_2_retorna_2(): void
    {
        // Prueba explícita del paso recursivo: 2 * factorial(1) = 2 * 1 = 2
        $this->assertEquals(2, factorial(2));
    }
}
```

